package io.github.diodeme.ji.host;

import io.github.diodeme.ji.extension.ProjectTrustStore;
import java.time.Clock;
import java.util.List;
import java.util.Locale;
import java.util.Objects;
import java.util.Optional;
import java.util.function.Function;
import java.util.function.Supplier;

/** Host-owned metadata projection and trust command boundary for workspace resources. */
public final class ResourceApplicationService {
    private final ProjectTrustStore.ProjectIdentity project;
    private final ProjectTrustStore trustStore;
    private final Supplier<Snapshot> snapshot;
    private final Function<ProjectTrustStore.TrustDecision, Snapshot> refresh;
    private final Clock clock;

    public ResourceApplicationService(
            ProjectTrustStore.ProjectIdentity project,
            ProjectTrustStore trustStore,
            Supplier<Snapshot> snapshot,
            Function<ProjectTrustStore.TrustDecision, Snapshot> refresh,
            Clock clock) {
        this.project = Objects.requireNonNull(project, "project");
        this.trustStore = Objects.requireNonNull(trustStore, "trustStore");
        this.snapshot = Objects.requireNonNull(snapshot, "snapshot");
        this.refresh = Objects.requireNonNull(refresh, "refresh");
        this.clock = Objects.requireNonNull(clock, "clock");
    }

    public Snapshot snapshot() {
        return snapshot.get();
    }

    public Trust trust() {
        Snapshot current = snapshot();
        ProjectTrustStore.TrustDecision decision = trustStore.find(project).orElse(null);
        return new Trust(project.value(), current.projectFingerprint(),
                decision == null ? "denied" : id(decision.decision()),
                decision == null ? 0 : decision.revision());
    }

    public Trust decide(long expectedRevision, String decisionId) {
        Snapshot current = snapshot();
        ProjectTrustStore.Decision decision;
        try {
            decision = ProjectTrustStore.Decision.valueOf(decisionId.toUpperCase(Locale.ROOT));
        } catch (IllegalArgumentException failure) {
            throw new IllegalArgumentException("unknown project trust decision", failure);
        }
        ProjectTrustStore.TrustDecision saved = trustStore.decide(new ProjectTrustStore.TrustCommand(
                project, new ProjectTrustStore.ProjectFingerprint(current.projectFingerprint()),
                decision, expectedRevision, clock.instant()));
        refresh.apply(saved);
        return new Trust(project.value(), saved.fingerprint().value(), id(saved.decision()), saved.revision());
    }

    private static String id(ProjectTrustStore.Decision decision) {
        return decision.name().toLowerCase(Locale.ROOT);
    }

    public record Snapshot(long generation, String projectFingerprint, boolean complete, List<Resource> items) {
        public Snapshot {
            if (generation < 0 || projectFingerprint == null
                    || !projectFingerprint.matches("[0-9a-f]{64}")) {
                throw new IllegalArgumentException("invalid resource snapshot");
            }
            items = List.copyOf(items);
        }
    }

    public record Resource(
            String resourceId, String kind, String scope, String sourceId, String logicalPath,
            String sourceRevision, String contentSha256, String state, String errorCode) {
        public Resource {
            resourceId = required(resourceId, "resourceId");
            kind = required(kind, "kind");
            scope = required(scope, "scope");
            sourceId = required(sourceId, "sourceId");
            logicalPath = required(logicalPath, "logicalPath");
            sourceRevision = required(sourceRevision, "sourceRevision");
            contentSha256 = required(contentSha256, "contentSha256");
            state = required(state, "state");
            errorCode = errorCode == null ? "" : errorCode;
        }
    }

    public record Trust(String projectId, String projectFingerprint, String decision, long revision) {
        public Trust {
            projectId = required(projectId, "projectId");
            projectFingerprint = required(projectFingerprint, "projectFingerprint");
            decision = required(decision, "decision");
            if (revision < 0) throw new IllegalArgumentException("revision must not be negative");
        }
    }

    private static String required(String value, String name) {
        if (value == null || value.isBlank()) throw new IllegalArgumentException(name + " must not be blank");
        return value;
    }
}
